<script setup lang="ts">
import {ref,computed} from 'vue';import {useRouter} from 'vue-router';import {Plus,ArrowUpRight} from 'lucide-vue-next';import {useApp} from '../store';
const app=useApp();const router=useRouter();const creating=ref(false);const title=ref('');const description=ref('');
const counts=computed(()=>{const lessonBook=new Map(app.data.lessons.map(l=>[l.id,l.bookId]));const out=new Map<string,{lessons:number;words:number}>();for(const b of app.data.books){const meta=app.metaBooks?.find(m=>m.id===b.id);out.set(b.id,{lessons:0,words:meta?.wordCount??0})}for(const l of app.data.lessons){const c=out.get(l.bookId);if(c)c.lessons++}const loadedWordCounts=new Map<string,number>();for(const w of app.data.words){const bookId=lessonBook.get(w.lessonId);if(bookId)loadedWordCounts.set(bookId,(loadedWordCounts.get(bookId)??0)+1)}for(const [bookId,count] of loadedWordCounts.entries()){const c=out.get(bookId);if(c)c.words=count}return out});
async function create(){const id=await app.addBook([],title.value,description.value);if(id)router.push('/books/'+id)}
</script>
<template><section class="page-heading"><div><p class="eyebrow">MY COLLECTION</p><h1>我的词书</h1><p class="muted">每一本词书，都是一段新的旅程。</p></div><div class="actions"><button @click="creating=!creating"><Plus :size="17"/> 创建词书</button><RouterLink class="button primary" to="/import">导入词书 <ArrowUpRight :size="17"/></RouterLink></div></section><form v-if="creating" class="form-panel" @submit.prevent="create"><label>词书名称<input v-model="title" required maxlength="100"/></label><label>简介<textarea v-model="description" maxlength="500"/></label><button class="primary" :disabled="app.busy">创建</button></form><div class="book-grid"><RouterLink v-for="(b,i) in app.data.books" :key="b.id" :to="'/books/'+b.id" class="library-book"><div class="book-jacket" :class="{alternate:i%2}"><small>日本語学習 · {{String(i+1).padStart(2,'0')}}</small><strong lang="ja">{{i%2?'学ぶ':'言葉'}}</strong><span>{{b.title}}</span></div><h3>{{b.title}}</h3><p>{{counts.get(b.id)?.lessons??0}} 课 <span>·</span> {{counts.get(b.id)?.words??0}} 词</p></RouterLink><RouterLink class="import-tile" to="/import"><Plus :size="28"/><h3>带上你的词书</h3><p>导入 CSV 或 JSON</p></RouterLink></div></template>
